                    child_spec_repr = _format_trace_value(child_spec, width - len(indent) - len(' |\\ Spec: '))
                    lines.append(f'{indent} |\\ Spec: {child_spec_repr}')
                    sub_child_errors = child_scope.maps[0].get(CHILD_ERRORS, [])
                    if sub_child_errors:
